    hr += seed; sbp += seed - 4;
    if (/出血|bleed|haemorrh|hemorrh|休克|shock|低血壓|hypotens/i.test(text)) { hr = 118 + seed; sbp = 84; dbp = 50; note = say('低血壓、心搏過速', 'hypotensive, tachycardic'); }
