    const sets = { cranial: [say('頭皮夾', 'scalp clips'), say('高速鑽／銑刀', 'craniotome'), say('硬腦膜剪', 'dural scissors'), say('顯微鏡＋雙極', 'microscope + bipolar'), say('骨瓣固定片', 'plates')], 'thorax-heart': [say('胸骨鋸', 'sternal saw'), say('心包牽開', 'pericardial stay'), say('插管＋肝素', 'cannulae + heparin'), say('血管吻合縫線', 'vascular sutures'), say('胸骨鋼絲', 'sternal wires')], 'thorax-lung': [say('胸腔鏡', 'thoracoscope'), say('內視鏡釘合器', 'endo-stapler'), say('超音波刀', 'energy device'), say('胸管', 'chest tube')], vessel: [say('血管鉗', 'vascular clamps'), say('Fogarty 導管', 'Fogarty catheter'), say('人工血管', 'graft'), say('血管縫線', 'Prolene')], bone: [say('復位鉗', 'reduction clamp'), say('鑽＋導引', 'drill + guide'), say('鋼板螺釘', 'plate & screws'), say('C 臂', 'C-arm')], cath: [say('橈動脈鞘', 'radial sheath'), say('導引導管', 'guide catheter'), say('導絲', 'guidewire'), say('球囊', 'balloon'), say('支架', 'stent')], abdomen: [say('氣腹針／套管', 'Veress / trocars'), say('抓鉗', 'graspers'), say('夾鉗／施夾器', 'clip applier'), say('取物袋', 'retrieval bag')], 'bedside-neuro': [say('反射槌', 'reflex hammer'), say('音叉', 'tuning fork'), say('手電筒', 'penlight'), say('NIHSS 表', 'NIHSS sheet')], bedside: [say('聽診器', 'stethoscope'), say('血壓計', 'BP cuff'), say('血氧計', 'pulse oximeter'), say('病歷', 'chart')], generic: [say('手術刀', 'scalpel'), say('止血鉗', 'haemostat'), say('縫線', 'sutures')] };
