    if (id === 'tray') return `<h4>🧰 ${say('器械台', 'Instrument tray')}</h4><p class="row">${instrumentsFor(fieldType(c), 1).concat([say('紗布 ×10', 'swabs ×10'), say('縫針 ×6', 'needles ×6')]).map(x => `<span class="chip small">${esc(x)}</span>`).join('')}</p><p class="small muted">${say('清點：術前、關閉體腔前、關閉皮膚前各一次；數字不符即停止。', 'Count before incision, before closing a cavity and before skin; stop on any discrepancy.')}</p>`;
    if (id === 'cart') return `<h4>💊 ${say('藥物車', 'Medication cart')}</h4><p class="small">${say('本站不提供劑量；藥名、濃度、途徑一律口頭覆誦。常見本科用藥請到配伍實驗室練習組合與交互作用。', 'No doses here; read back name, concentration and route. Practise this department’s combinations and interactions in the pharmacy lab.')}</p><p><a class="button small" href="#pharmacy?tab=drug">${say('開啟配伍實驗室 →', 'Open the pharmacy lab →')}</a></p>`;
