    if (id === 'device') { const d = c.department || ''; const name = /cardiac-surg/.test(d) ? say('體外循環機／心臟停搏液', 'Heart-lung machine / cardioplegia') : /neurosurg/.test(d) ? say('顯微鏡、導航、神經監測（MER／IONM）', 'Microscope, navigation, neuromonitoring (MER / IONM)') : /cardiology/.test(d) ? say('導管室 C 臂、IVUS／FFR、IABP', 'Cath-lab C-arm, IVUS / FFR, IABP') : /thoracic/.test(d) ? say('胸腔鏡塔、雙腔氣管內管', 'VATS tower, double-lumen tube') : /vascular/.test(d) ? say('複合手術室 C 臂、血管內裝置', 'Hybrid-suite C-arm, endovascular devices') : /ortho/.test(d) ? say('C 臂透視、牽引床、動力工具', 'C-arm, traction table, power tools') : say('本科專用設備', 'Department device'); return `<h4>⚙ ${esc(name)}</h4><p class="small">${say('設定與參數由專責人員操作；學徒負責核對開機自檢、警報上下限與備援。', 'Set-up and parameters belong to the specialist; the intern verifies self-test, alarm limits and backup.')}</p>`; }
