    let mentorPos = null;
    if (ctx.mentorAt && target) { const hs = HOTSPOTS[target.hotspot]; const k = Math.max(0, Math.min(1, (ctx.mentorAt.x - 8) / Math.max(1, (engine.anchors[s.zone][0] - 8)))); const home = roles.find(r => r.id === 'mentor'); mentorPos = { x: home.x + (hs.x - home.x) * k, y: home.y + 40 + (hs.y - home.y - 40) * k }; }
    const pins = map.map(m => { const hs = HOTSPOTS[m.hotspot]; const x = hs.x + (m.slot % 3) * 26 - 26, y = hs.y - 30 - Math.floor(m.slot / 3) * 24; const isT = m.station === s.zone, isS = s.secondZone === m.station, done = m.station < engine.index && !ctx.singleStage; return `<g class="th-pin ${isT || isS ? 'target' : ''} ${done ? 'done' : ''}" data-zone="${m.station}" transform="translate(${x} ${y})" role="button" tabindex="0" aria-label="${esc(pk(c.tiles[m.station]))}"><circle r="13" fill="${isT || isS ? '#c0392b' : done ? '#287a55' : '#1f6f5f'}" stroke="#fff" stroke-width="2"/><text y="4" text-anchor="middle" font-size="12" font-weight="800" fill="#fff">${m.station + 1}</text>${isT || isS ? `<text y="-20" text-anchor="middle" font-size="22" fill="#c0392b" class="th-arrow">↓</text><text y="34" text-anchor="middle" font-size="11" font-weight="700" fill="#7a1c24">${esc(pk(c.tiles[m.station]))}</text>` : ''}</g>`; }).join('');
    const hotspots = Object.entries(HOTSPOTS).map(([id, hs]) => `<g class="th-hot ${target && target.hotspot === id ? 'target' : ''}" data-hot="${id}" transform="translate(${hs.x} ${hs.y})" role="button" tabindex="0" aria-label="${esc(pk(hs))}"><circle r="26" fill="rgba(255,255,255,.55)" stroke="${target && target.hotspot === id ? '#c0392b' : '#4f7f7a'}" stroke-width="${target && target.hotspot === id ? 4 : 2}"/><text y="7" text-anchor="middle" font-size="22">${hs.icon}</text><text y="46" text-anchor="middle" font-size="11" fill="#1d2a2a" font-weight="600">${esc(pk(hs))}</text></g>`).join('');
    const hands = ['left', 'right'].map(h => { const p = engine.hands[h]; if (!p.moved) return ''; const z = engine.anchors.findIndex(a => Math.hypot(a[0] - p.x, a[1] - p.y) <= engine.tolerance); const m = z >= 0 ? map[z] : null; if (!m) return ''; const hs = HOTSPOTS[m.hotspot]; return `<g transform="translate(${hs.x + (h === 'left' ? -34 : 34)} ${hs.y + 10})"><circle r="15" fill="${h === 'left' ? '#14508d' : '#715021'}" stroke="#fff" stroke-width="3"/><text y="5" text-anchor="middle" font-size="13" font-weight="800" fill="#fff">${h === 'left' ? 'L' : 'R'}</text></g>`; }).join('');
    const avatars = roles.map(r => avatar(r.id === 'mentor' && mentorPos ? Object.assign({}, r, mentorPos) : r, { active: lines.some(l => l.role === r.id) })).join('');
    const bubbles = lines.slice(0, 2).map((l, i) => { const r = roles.find(x => x.id === l.role); if (!r) return ''; const pos = r.id === 'mentor' && mentorPos ? mentorPos : r; return bubble(pos.x, pos.y - 30, l.text, pos.x > 700); }).join('');
